-- Arbeitsrecht Berufsbildung > Pflichten von Auszubildenden > Verschwiegenheit über Betriebsgeheimnisse (§ 13 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker über vertrauliche Kundendaten schweigen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG fordert Verschwiegenheit über Betriebsgeheimnisse"}, {"text": "Nein", "correct": false, "because": "Verschwiegenheit ist eine gesetzliche Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker betriebliche Passwörter an Freunde weitergeben?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG verbietet die Weitergabe von Betriebsgeheimnissen"}, {"text": "Ja", "correct": false, "because": "Das wäre ein Verstoß gegen die Verschwiegenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Fachinformatiker verpflichtet, nach Ausbildungsende über Betriebsgeheimnisse zu schweigen?', 2, '[{"text": "Ja", "correct": true, "because": "Die Verschwiegenheitspflicht gilt auch nach § 13 BBiG über die Ausbildung hinaus"}, {"text": "Nein", "correct": false, "because": "Die Pflicht bleibt bestehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker Quellcode des Betriebs öffentlich teilen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG schützt Betriebsgeheimnisse wie Quellcode"}, {"text": "Ja", "correct": false, "because": "Das verstößt gegen die Verschwiegenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker sensible Netzwerkdaten vor Kollegen verbergen?', 2, '[{"text": "Nein", "correct": true, "because": "Verschwiegenheit gilt gegenüber Dritten, nicht zwingend Kollegen"}, {"text": "Ja", "correct": false, "because": "Kollegen sind oft berechtigt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Fachinformatiker zur Verschwiegenheit über Betriebsgeheimnisse?', 2, '[{"text": "§ 13 BBiG", "correct": true, "because": "Regelt die Pflichten des Auszubildenden"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Betriebs"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er versehentlich ein Betriebsgeheimnis preisgibt?', 3, '[{"text": "Den Betrieb sofort informieren", "correct": true, "because": "§ 13 BBiG fordert verantwortliches Verhalten"}, {"text": "Es verschweigen", "correct": false, "because": "Das verschlimmert den Verstoß"}, {"text": "Die IHK kontaktieren", "correct": false, "because": "Nicht primäre Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information fällt unter die Verschwiegenheitspflicht eines Fachinformatikers?', 3, '[{"text": "Kundendaten des Betriebs", "correct": true, "because": "Betriebsgeheimnisse gemäß § 13 BBiG"}, {"text": "Seine persönlichen Lernziele", "correct": false, "because": "Keine Betriebsgeheimnisse"}, {"text": "Öffentliche Betriebszeiten", "correct": false, "because": "Nicht vertraulich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer kann einen Fachinformatiker von der Verschwiegenheitspflicht entbinden?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "Nur der Betrieb kann dies erlauben"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat keine Befugnis"}, {"text": "Der Auszubildende selbst", "correct": false, "because": "Keine Eigenermächtigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker Betriebsgeheimnisse weitergibt?', 3, '[{"text": "Er kann gekündigt und haftbar gemacht werden", "correct": true, "because": "Verstoß gegen § 13 BBiG hat Konsequenzen"}, {"text": "Nichts passiert", "correct": false, "because": "Ein Verstoß hat Folgen"}, {"text": "Die IHK übernimmt die Verantwortung", "correct": false, "because": "IHK ist nicht zuständig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Informationen muss ein Fachinformatiker gemäß § 13 BBiG geheim halten?', 4, '[{"text": "Interner Quellcode", "correct": true, "because": "Betriebsgeheimnis"}, {"text": "Kundendatenbanken", "correct": true, "because": "Vertrauliche Daten"}, {"text": "Seine persönliche Meinung", "correct": false, "because": "Kein Betriebsgeheimnis"}, {"text": "Netzwerkkonfigurationen", "correct": true, "because": "Sensible betriebliche Information"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Handlungen verstoßen gegen die Verschwiegenheitspflicht eines Fachinformatikers?', 3, '[{"text": "Quellcode auf GitHub hochladen", "correct": true, "because": "Verstoß gegen § 13 BBiG"}, {"text": "Kundendaten an Dritte weitergeben", "correct": true, "because": "Vertraulichkeit verletzt"}, {"text": "Mit Kollegen über Projekte sprechen", "correct": false, "because": "Interner Austausch erlaubt"}, {"text": "Passwörter öffentlich teilen", "correct": true, "because": "Schwere Verletzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ein Fachinformatiker tun, wenn er unsicher ist, ob etwas ein Betriebsgeheimnis ist?', 3, '[{"text": "Den Ausbilder fragen", "correct": true, "because": "Klarheit vom Betrieb einholen"}, {"text": "Die IHK informieren", "correct": false, "because": "Nicht primäre Anlaufstelle"}, {"text": "Mit Kollegen besprechen", "correct": true, "because": "Interner Austausch möglich"}, {"text": "Es trotzdem teilen", "correct": false, "because": "Riskiert Verstoß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Fachinformatiker bei Verletzung der Verschwiegenheit?', 4, '[{"text": "Abmahnung durch den Betrieb", "correct": true, "because": "Reaktion auf Pflichtverletzung"}, {"text": "Kündigung bei schwerem Verstoß", "correct": true, "because": "§ 22 BBiG erlaubt dies"}, {"text": "Schadensersatzforderungen", "correct": true, "because": "Bei Schaden möglich"}, {"text": "Automatische Beförderung", "correct": false, "because": "Nicht logisch"}]'),
('00000000-0000-0000-0000-000000000000', 'In welchen Situationen darf ein Fachinformatiker Betriebsgeheimnisse offenlegen?', 3, '[{"text": "Mit Zustimmung des Betriebs", "correct": true, "because": "Betrieb kann entbinden"}, {"text": "Vor Gericht bei Aussagepflicht", "correct": true, "because": "Gesetzliche Ausnahme"}, {"text": "An Freunde aus Neugier", "correct": false, "because": "Verstoß gegen § 13 BBiG"}, {"text": "Bei der IHK-Prüfung", "correct": false, "because": "Nicht erforderlich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Fachinformatiker darf Betriebsgeheimnisse nur mit Erlaubnis teilen. b) Die Verschwiegenheit endet mit der Ausbildung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erlaubnis nötig, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kundendaten sind Betriebsgeheimnisse. b) Ein Fachinformatiker darf sie Kollegen mitteilen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides kann richtig sein"}, {"text": "Beides stimmt", "correct": true, "because": "Kundendaten sind geheim, Kollegen oft berechtigt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschwiegenheit gilt auch nach der Ausbildung. b) Ein Fachinformatiker kann Quellcode privat nutzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschwiegenheit bleibt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker darf Netzwerkdaten an Dritte weitergeben. b) Verstöße gegen die Verschwiegenheit können zur Kündigung führen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Kündigung möglich, a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) § 13 BBiG schützt Betriebsgeheimnisse. b) Ein Fachinformatiker darf Passwörter mit Familie teilen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "§ 13 BBiG gilt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

